const I = (id, name, cat, w, d, h, c, make, extra = {}) => ({ id, name, cat, w, d, h, color: c, make, ...extra });
const at = (g, x, y, z, ry = 0) => { g.position.set(x, y, z); g.rotation.y = ry; return g; };
const face = m => turn(m, Math.PI / 2);                     // stand a disc up so it faces the front
const side = m => turn(m, 0, 0, Math.PI / 2);               // lay a cylinder on its side (left-right)

