const prism = (w, d, h, m, y) => { const s = new THREE.Shape(); s.moveTo(-w / 2, 0); s.lineTo(w / 2, 0); s.lineTo(0, h); s.closePath(); const g = new THREE.ExtrudeGeometry(s, { depth: d, bevelEnabled: false }); g.translate(0, 0, -d / 2); const me = new THREE.Mesh(g, box(0.01, 0.01, 0.01, m).material); me.position.y = y; return me; };
